// Hand-authored Indeed commands (no "Generated by CLI Printing Press" header,
// so they survive `generate --force` and regen-merge). These implement the
// headline job-search surface on top of the generated Surf client and store:
// the public Indeed website serves job data as JSON embedded in server-rendered
// HTML, so these commands fetch the page and parse it via internal/indeedparse
// rather than hitting a JSON API.
package cli

import (
	"context"
	"encoding/json"
	"fmt"
	"os/exec"
	"runtime"
	"sort"
	"strconv"
	"strings"
	"time"

	"github.com/spf13/cobra"

	"github.com/mvanhorn/printing-press-library/library/productivity/indeed/internal/cliutil"
	"github.com/mvanhorn/printing-press-library/library/productivity/indeed/internal/indeedparse"
	"github.com/mvanhorn/printing-press-library/library/productivity/indeed/internal/store"
)

const indeedCLIName = "indeed-pp-cli"
const jobsPerPage = 10
const viewJobBase = "https://www.indeed.com/viewjob?jk="

// maxSeenKeys bounds a saved search's persisted seen-key history so repeated
// `new` polls can't grow the stored blob indefinitely.
const maxSeenKeys = 2000

// validJobTypes are the values Indeed's `jt` query param accepts.
var validJobTypes = map[string]bool{
	"fulltime": true, "parttime": true, "contract": true,
	"internship": true, "temporary": true,
}

// searchFilters captures every search knob; shared by `search`, `saved save`,
// and `new` so a saved search re-runs identically.
type searchFilters struct {
	Query     string  `json:"query"`
	Location  string  `json:"location,omitempty"`
	Radius    int     `json:"radius,omitempty"`
	Posted    int     `json:"posted,omitempty"` // fromage days
	Sort      string  `json:"sort,omitempty"`   // date|relevance
	JobType   string  `json:"jobType,omitempty"`
	Remote    bool    `json:"remote,omitempty"`
	MinSalary float64 `json:"minSalary,omitempty"`
	Limit     int     `json:"limit,omitempty"`
}

func openIndeedStore(ctx context.Context) (*store.Store, error) {
	return store.OpenWithContext(ctx, defaultDBPath(indeedCLIName))
}

// storeJob persists a job into the generic resources table (resource_type
// "job") so the framework search/sql/context commands and our offline `find`
// see it.
// storeJob caches a job in the local store. It returns any error so callers
// can surface a persistence failure rather than silently dropping the cache
// write (which would also defeat offline `find` and the saved-search history).
func storeJob(db *store.Store, j indeedparse.Job) error {
	raw, err := json.Marshal(j)
	if err != nil {
		return err
	}
	return db.Upsert("job", j.Key, raw)
}

// buildSearchParams maps filters to Indeed web /jobs query params.
func buildSearchParams(f searchFilters, location string, start int) map[string]string {
	params := map[string]string{}
	if f.Query != "" {
		params["q"] = f.Query
	}
	loc := location
	if f.Remote && loc == "" {
		loc = "Remote"
	}
	if loc != "" {
		params["l"] = loc
	}
	if f.Remote {
		// Remote attribute filter (DSQF7) so remote stays scoped even with a city.
		params["sc"] = "0kf:attr(DSQF7);"
	}
	if f.Radius > 0 {
		params["radius"] = strconv.Itoa(f.Radius)
	}
	if f.Posted > 0 {
		params["fromage"] = strconv.Itoa(f.Posted)
	}
	if f.Sort == "date" {
		params["sort"] = "date"
	}
	if f.JobType != "" {
		params["jt"] = f.JobType
	}
	if start > 0 {
		params["start"] = strconv.Itoa(start)
	}
	return params
}

func salaryMeets(j indeedparse.Job, floor float64) bool {
	if floor <= 0 {
		return true
	}
	// Compare on an annualized basis when we know the period; otherwise use the
	// raw figure. Filter on the normalized minimum (the bottom of the posted
	// range) so a job whose floor is below the threshold is dropped — a user
	// who sets --min-salary 120000 does not want roles that *might* pay less.
	annual := func(v float64, period string) float64 {
		switch period {
		case "hour":
			return v * 2080
		case "day":
			return v * 260
		case "week":
			return v * 52
		case "month":
			return v * 12
		default:
			return v
		}
	}
	bottom := j.SalaryMin
	if bottom == 0 {
		bottom = j.SalaryMax // single-figure posting (no explicit range)
	}
	if bottom == 0 {
		return false // no salary info → can't clear an explicit floor
	}
	return annual(bottom, j.SalaryPeriod) >= floor
}

func splitCSV(s string) []string {
	var out []string
	for _, p := range strings.Split(s, ",") {
		if p = strings.TrimSpace(p); p != "" {
			out = append(out, p)
		}
	}
	if len(out) == 0 {
		out = []string{""}
	}
	return out
}

// runSearch executes a search across one or more locations, dedups by job key,
// stores every job seen, and returns the (optionally salary-filtered) results
// plus the highest totalJobCount reported.
func runSearch(cmd *cobra.Command, flags *rootFlags, f searchFilters) ([]indeedparse.Job, int, error) {
	c, err := flags.newClient()
	if err != nil {
		return nil, 0, err
	}
	ctx := cmd.Context()

	perLoc := f.Limit
	if perLoc <= 0 {
		perLoc = 25
	}
	if cliutil.IsDogfoodEnv() && perLoc > jobsPerPage {
		perLoc = jobsPerPage // one page under live-dogfood's per-command timeout
	}

	locations := splitCSV(f.Location)

	// locFetch carries one location's deduped jobs plus the highest
	// totalJobCount Indeed reported for that location's query — the "~47,000
	// jobs found" scale figure, which is independent of how many we paged in.
	type locFetch struct {
		Jobs  []indeedparse.Job
		Total int
	}

	fetchLoc := func(ctx context.Context, loc string) (locFetch, error) {
		var collected []indeedparse.Job
		maxTotal := 0
		seen := map[string]bool{}
		for start := 0; len(collected) < perLoc; start += jobsPerPage {
			params := buildSearchParams(f, loc, start)
			html, err := c.GetNoCache(ctx, "/jobs", params)
			if err != nil {
				if start == 0 {
					return locFetch{}, classifyAPIError(err, flags)
				}
				break // later page failed; keep what we have
			}
			jobs, total, perr := indeedparse.ParseSearchResults(html)
			if perr != nil {
				if start == 0 {
					return locFetch{}, perr
				}
				break
			}
			if total > maxTotal {
				maxTotal = total
			}
			if len(jobs) == 0 {
				break
			}
			for _, j := range jobs {
				if !seen[j.Key] {
					seen[j.Key] = true
					collected = append(collected, j)
				}
			}
			if len(jobs) < jobsPerPage {
				break // last page
			}
		}
		return locFetch{Jobs: collected, Total: maxTotal}, nil
	}

	// Single location: run directly so a hard error surfaces as the command
	// error. Multi-location: fan out so one bad location doesn't drop the rest.
	var perLocResults []locFetch
	if len(locations) == 1 {
		lf, err := fetchLoc(ctx, locations[0])
		if err != nil {
			return nil, 0, err
		}
		perLocResults = append(perLocResults, lf)
	} else {
		results, errs := cliutil.FanoutRun(ctx, locations,
			func(l string) string { return l },
			fetchLoc,
			cliutil.WithConcurrency(2),
		)
		cliutil.FanoutReportErrors(cmd.ErrOrStderr(), errs)
		for _, r := range results {
			// A location that succeeded but matched nothing is dropped
			// silently otherwise; surface it so a user fanning out across
			// "Austin,Dallas,Remote" knows which leg contributed zero.
			if len(r.Value.Jobs) == 0 {
				fmt.Fprintf(cmd.ErrOrStderr(), "note: location %q returned no jobs\n", r.Source)
			}
			perLocResults = append(perLocResults, r.Value)
		}
		if len(results) == 0 {
			return nil, 0, fmt.Errorf("all %d locations failed", len(locations))
		}
	}

	// Merge in location order, dedup by key, store everything, then filter.
	// totalReported is the sum of each location's reported scale so the footer
	// reflects Indeed's actual result volume across the searched locations, not
	// the number of rows we happened to page in.
	byKey := map[string]bool{}
	var merged []indeedparse.Job
	totalReported := 0
	for _, lf := range perLocResults {
		totalReported += lf.Total
		for _, j := range lf.Jobs {
			if !byKey[j.Key] {
				byKey[j.Key] = true
				merged = append(merged, j)
			}
		}
	}
	if db, derr := openIndeedStore(ctx); derr == nil {
		stored := 0
		var firstErr error
		for _, j := range merged {
			if err := storeJob(db, j); err != nil {
				if firstErr == nil {
					firstErr = err
				}
				continue
			}
			stored++
		}
		db.Close()
		if firstErr != nil {
			fmt.Fprintf(cmd.ErrOrStderr(), "warning: cached %d/%d jobs locally (offline `find` and saved-search history may be incomplete): %v\n", stored, len(merged), firstErr)
		}
	} else {
		fmt.Fprintf(cmd.ErrOrStderr(), "warning: could not open local store (%v); results not cached for offline use\n", derr)
	}

	var out []indeedparse.Job
	for _, j := range merged {
		if !salaryMeets(j, f.MinSalary) {
			continue
		}
		out = append(out, j)
		if f.Limit > 0 && len(out) >= f.Limit {
			break
		}
	}
	// Fall back to the local count if Indeed reported no scale figure, so the
	// footer never claims fewer total than we actually returned.
	if totalReported < len(merged) {
		totalReported = len(merged)
	}
	return out, totalReported, nil
}

func newSearchCmd(flags *rootFlags) *cobra.Command {
	var f searchFilters
	cmd := &cobra.Command{
		Use:   "search [query]",
		Short: "Search Indeed job listings (live).",
		Long: "Search Indeed job listings live and store every result locally for offline\n" +
			"search (`find`) and new-since-last-run tracking (`saved`/`new`).\n\n" +
			"Pass a location list (comma-separated) to fan out across cities and dedup.",
		Example: strings.Trim(`
  indeed-pp-cli search "software engineer" --location Remote
  indeed-pp-cli search "data scientist" --location "Austin, TX" --posted 7 --sort date --json
  indeed-pp-cli search "product manager" --location "Austin,Dallas,Remote" --min-salary 130000
  indeed-pp-cli search "rust" --job-type fulltime --remote --limit 50 --json --select key,title,company,salary
`, "\n"),
		Annotations: map[string]string{"mcp:read-only": "true"},
		RunE: func(cmd *cobra.Command, args []string) error {
			f.Query = strings.TrimSpace(strings.Join(args, " "))
			// --remote alone is a valid invocation (buildSearchParams maps it to
			// l=Remote), so don't fall through to help when only --remote is set.
			if f.Query == "" && f.Location == "" && !f.Remote {
				return cmd.Help()
			}
			if f.JobType != "" && !validJobTypes[f.JobType] {
				return fmt.Errorf("--job-type %q is invalid; use one of: fulltime, parttime, contract, internship, temporary", f.JobType)
			}
			if f.Sort != "" && f.Sort != "date" && f.Sort != "relevance" {
				return fmt.Errorf("--sort %q is invalid; use \"date\" or \"relevance\"", f.Sort)
			}
			if dryRunOK(flags) {
				return nil
			}
			jobs, total, err := runSearch(cmd, flags, f)
			if err != nil {
				return err
			}
			return emitJobs(cmd, flags, jobs, total)
		},
	}
	addSearchFlags(cmd, &f)
	cmd.Flags().IntVar(&f.Limit, "limit", 25, "Maximum results to return (paginates as needed).")
	return cmd
}

// addSearchFlags wires the shared filter flags (everything except --limit,
// which `search` owns but `saved save` derives from the query).
func addSearchFlags(cmd *cobra.Command, f *searchFilters) {
	cmd.Flags().StringVarP(&f.Location, "location", "l", "", "City, state, zip, or \"Remote\". Comma-separated for multi-location fan-out.")
	cmd.Flags().IntVar(&f.Radius, "radius", 0, "Search radius in miles.")
	cmd.Flags().IntVar(&f.Posted, "posted", 0, "Only jobs posted within this many days (1, 3, 7, 14).")
	cmd.Flags().StringVar(&f.Sort, "sort", "", "Sort order: \"date\" or \"relevance\" (default relevance).")
	cmd.Flags().StringVar(&f.JobType, "job-type", "", "Job type: fulltime, parttime, contract, internship, temporary.")
	cmd.Flags().BoolVar(&f.Remote, "remote", false, "Only remote jobs.")
	cmd.Flags().Float64Var(&f.MinSalary, "min-salary", 0, "Drop jobs whose parsed salary floor (annualized minimum) is below this.")
}

// emitJobs renders a slice of jobs in the active output mode.
func emitJobs(cmd *cobra.Command, flags *rootFlags, jobs []indeedparse.Job, total int) error {
	if jobs == nil {
		jobs = []indeedparse.Job{}
	}
	if flags.asJSON || !isTerminal(cmd.OutOrStdout()) {
		return printJSONFiltered(cmd.OutOrStdout(), jobs, flags)
	}
	if len(jobs) == 0 {
		fmt.Fprintln(cmd.OutOrStdout(), "No jobs found.")
		return nil
	}
	for _, j := range jobs {
		fmt.Fprintf(cmd.OutOrStdout(), "%s\n  %s", j.Title, j.Company)
		if j.Location != "" {
			fmt.Fprintf(cmd.OutOrStdout(), " · %s", j.Location)
		}
		if j.Salary != "" {
			fmt.Fprintf(cmd.OutOrStdout(), " · %s", j.Salary)
		}
		if j.Posted != "" {
			fmt.Fprintf(cmd.OutOrStdout(), " · %s", j.Posted)
		}
		fmt.Fprintf(cmd.OutOrStdout(), "\n  %s\n  %s\n\n", j.Key, j.URL)
	}
	if total > len(jobs) {
		fmt.Fprintf(cmd.OutOrStdout(), "Showing %d of ~%d matching jobs. Use --limit to fetch more, --json for full data.\n", len(jobs), total)
	}
	return nil
}

func newJobCmd(flags *rootFlags) *cobra.Command {
	cmd := &cobra.Command{
		Use:   "job",
		Short: "Look up a single job by key.",
		RunE:  parentNoSubcommandRunE(flags),
	}
	cmd.AddCommand(newJobGetCmd(flags))
	return cmd
}

func newJobGetCmd(flags *rootFlags) *cobra.Command {
	cmd := &cobra.Command{
		Use:         "get <job-key>",
		Short:       "Get full detail for a job, including the description.",
		Long:        "Fetch a job's full detail (description, employment type, dates) by its key.\nGet a key from `search` output.",
		Example:     "  indeed-pp-cli job get 3700db3b90d43bc1 --json",
		Annotations: map[string]string{"mcp:read-only": "true"},
		RunE: func(cmd *cobra.Command, args []string) error {
			if len(args) == 0 {
				return cmd.Help()
			}
			if dryRunOK(flags) {
				return nil
			}
			key := args[0]
			c, err := flags.newClient()
			if err != nil {
				return err
			}
			html, err := c.GetNoCache(cmd.Context(), "/viewjob", map[string]string{"jk": key})
			if err != nil {
				return classifyAPIError(err, flags)
			}
			detail, err := indeedparse.ParseJobDetail(html, key)
			if err != nil {
				return err
			}
			if flags.asJSON || !isTerminal(cmd.OutOrStdout()) {
				return printJSONFiltered(cmd.OutOrStdout(), detail, flags)
			}
			w := cmd.OutOrStdout()
			fmt.Fprintf(w, "%s\n%s", detail.Title, detail.Company)
			if detail.Location != "" {
				fmt.Fprintf(w, " · %s", detail.Location)
			}
			if detail.EmploymentType != "" {
				fmt.Fprintf(w, " · %s", detail.EmploymentType)
			}
			fmt.Fprintf(w, "\n%s\n", detail.URL)
			if detail.DatePosted != "" {
				fmt.Fprintf(w, "Posted: %s\n", detail.DatePosted)
			}
			fmt.Fprintf(w, "\n%s\n", detail.Description)
			return nil
		},
	}
	return cmd
}

// jobShape unmarshals stored data and reports whether it looks like a Job.
func asJob(raw json.RawMessage) (indeedparse.Job, bool) {
	var j indeedparse.Job
	if json.Unmarshal(raw, &j) != nil {
		return j, false
	}
	if j.Key == "" || j.Title == "" {
		return j, false
	}
	return j, true
}

func newFindCmd(flags *rootFlags) *cobra.Command {
	var limit int
	cmd := &cobra.Command{
		Use:     "find [terms]",
		Short:   "Offline full-text search across every job you've synced.",
		Long:    "Full-text search the local store of jobs you've already pulled with `search`.\nWorks with no network connection.",
		Example: "  indeed-pp-cli find \"rust kubernetes\" --json --select key,title,company",
		// A query that matches nothing is a valid empty result, not an error.
		Annotations: map[string]string{"mcp:read-only": "true", "pp:no-error-path-probe": "true"},
		RunE: func(cmd *cobra.Command, args []string) error {
			query := strings.TrimSpace(strings.Join(args, " "))
			if query == "" {
				return cmd.Help()
			}
			if dryRunOK(flags) {
				return nil
			}
			db, err := openIndeedStore(cmd.Context())
			if err != nil {
				return err
			}
			defer db.Close()
			rows, err := db.Search(query, limit*3+30)
			if err != nil {
				return fmt.Errorf("searching local store: %w", err)
			}
			var jobs []indeedparse.Job
			for _, r := range rows {
				if j, ok := asJob(r); ok {
					jobs = append(jobs, j)
					if len(jobs) >= limit {
						break
					}
				}
			}
			return emitJobs(cmd, flags, jobs, len(jobs))
		},
	}
	cmd.Flags().IntVar(&limit, "limit", 25, "Maximum results to return.")
	return cmd
}

func newCompanyCmd(flags *rootFlags) *cobra.Command {
	cmd := &cobra.Command{
		Use:     "company <name>",
		Short:   "Summarize a company from the jobs you've seen.",
		Long:    "Aggregate what the local store knows about a company: its Indeed rating,\nreview count, and the jobs you've pulled from it. Run `search` first to populate it.",
		Example: "  indeed-pp-cli company \"Acme Corp\" --json",
		// A company with no stored jobs is a valid empty result, not an error.
		Annotations: map[string]string{"mcp:read-only": "true", "pp:no-error-path-probe": "true"},
		RunE: func(cmd *cobra.Command, args []string) error {
			if len(args) == 0 {
				return cmd.Help()
			}
			if dryRunOK(flags) {
				return nil
			}
			name := strings.ToLower(strings.TrimSpace(strings.Join(args, " ")))
			db, err := openIndeedStore(cmd.Context())
			if err != nil {
				return err
			}
			defer db.Close()
			// Scan the full job history (no row cap) so the summary can't
			// silently miss a company's jobs once the local store grows large.
			raws, err := db.ListAll(cmd.Context(), "job")
			if err != nil {
				return err
			}
			type companySummary struct {
				Company     string            `json:"company"`
				Rating      float64           `json:"rating,omitempty"`
				ReviewCount int               `json:"reviewCount,omitempty"`
				JobCount    int               `json:"jobCount"`
				Jobs        []indeedparse.Job `json:"jobs"`
			}
			var sum companySummary
			sum.Jobs = []indeedparse.Job{}
			for _, r := range raws {
				j, ok := asJob(r)
				if !ok || !strings.Contains(strings.ToLower(j.Company), name) {
					continue
				}
				if sum.Company == "" {
					sum.Company = j.Company
				}
				if j.CompanyRating > sum.Rating {
					sum.Rating = j.CompanyRating
					sum.ReviewCount = j.ReviewCount
				}
				sum.Jobs = append(sum.Jobs, j)
			}
			sum.JobCount = len(sum.Jobs)
			if sum.JobCount == 0 {
				if flags.asJSON || !isTerminal(cmd.OutOrStdout()) {
					return printJSONFiltered(cmd.OutOrStdout(), sum, flags)
				}
				fmt.Fprintf(cmd.OutOrStdout(), "No jobs stored for a company matching %q. Run `%s search` for it first.\n", args[0], indeedCLIName)
				return nil
			}
			if flags.asJSON || !isTerminal(cmd.OutOrStdout()) {
				return printJSONFiltered(cmd.OutOrStdout(), sum, flags)
			}
			fmt.Fprintf(cmd.OutOrStdout(), "%s", sum.Company)
			if sum.Rating > 0 {
				fmt.Fprintf(cmd.OutOrStdout(), " · %.1f★ (%d reviews)", sum.Rating, sum.ReviewCount)
			}
			fmt.Fprintf(cmd.OutOrStdout(), "\n%d job(s) seen:\n\n", sum.JobCount)
			for _, j := range sum.Jobs {
				fmt.Fprintf(cmd.OutOrStdout(), "  %s · %s · %s\n", j.Title, j.Location, j.Key)
			}
			return nil
		},
	}
	return cmd
}

// --- saved searches + new ---

type savedSearch struct {
	Name     string        `json:"name"`
	Filters  searchFilters `json:"filters"`
	SeenKeys []string      `json:"seenKeys"`
	LastRun  string        `json:"lastRun,omitempty"`
	Created  string        `json:"created,omitempty"`
}

func newSavedCmd(flags *rootFlags) *cobra.Command {
	cmd := &cobra.Command{
		Use:   "saved",
		Short: "Manage named, re-runnable searches.",
		RunE:  parentNoSubcommandRunE(flags),
	}
	cmd.AddCommand(newSavedSaveCmd(flags), newSavedListCmd(flags), newSavedShowCmd(flags), newSavedDeleteCmd(flags))
	return cmd
}

func newSavedSaveCmd(flags *rootFlags) *cobra.Command {
	var f searchFilters
	cmd := &cobra.Command{
		Use:         "save <name> [query]",
		Short:       "Save a named search with its filters.",
		Long:        "Persist a named query + filters so you can re-run it with `new <name>`\nand see only postings that appeared since the last run.",
		Example:     "  indeed-pp-cli saved save daily-remote \"software engineer\" --location Remote --posted 1 --sort date",
		Annotations: map[string]string{"mcp:read-only": "true"},
		RunE: func(cmd *cobra.Command, args []string) error {
			if len(args) == 0 {
				return cmd.Help()
			}
			if dryRunOK(flags) {
				return nil
			}
			name := args[0]
			f.Query = strings.TrimSpace(strings.Join(args[1:], " "))
			// --remote alone is a valid saved search (mirrors the search guard);
			// don't reject a remote-only query.
			if f.Query == "" && f.Location == "" && !f.Remote {
				return fmt.Errorf("a saved search needs a query, --location, or --remote")
			}
			db, err := openIndeedStore(cmd.Context())
			if err != nil {
				return err
			}
			defer db.Close()
			ss := savedSearch{Name: name, Filters: f, SeenKeys: []string{}, Created: time.Now().UTC().Format(time.RFC3339)}
			raw, _ := json.Marshal(ss)
			if err := db.Upsert("saved_search", name, raw); err != nil {
				return err
			}
			if flags.asJSON {
				return printJSONFiltered(cmd.OutOrStdout(), ss, flags)
			}
			fmt.Fprintf(cmd.OutOrStdout(), "Saved search %q. Run `%s new %s` to poll it.\n", name, indeedCLIName, name)
			return nil
		},
	}
	addSearchFlags(cmd, &f)
	return cmd
}

func newSavedListCmd(flags *rootFlags) *cobra.Command {
	return &cobra.Command{
		Use:         "list",
		Short:       "List saved searches with their stored filters.",
		Example:     "  indeed-pp-cli saved list --json",
		Annotations: map[string]string{"mcp:read-only": "true"},
		RunE: func(cmd *cobra.Command, args []string) error {
			db, err := openIndeedStore(cmd.Context())
			if err != nil {
				return err
			}
			defer db.Close()
			raws, err := db.List("saved_search", 500)
			if err != nil {
				return err
			}
			var list []savedSearch
			for _, r := range raws {
				var ss savedSearch
				if json.Unmarshal(r, &ss) == nil {
					list = append(list, ss)
				}
			}
			sort.Slice(list, func(i, j int) bool { return list[i].Name < list[j].Name })
			if list == nil {
				list = []savedSearch{}
			}
			if flags.asJSON || !isTerminal(cmd.OutOrStdout()) {
				return printJSONFiltered(cmd.OutOrStdout(), list, flags)
			}
			if len(list) == 0 {
				fmt.Fprintln(cmd.OutOrStdout(), "No saved searches. Create one with `saved save`.")
				return nil
			}
			for _, ss := range list {
				fmt.Fprintf(cmd.OutOrStdout(), "%-20s  %q  loc=%q  (seen %d, last run %s)\n", ss.Name, ss.Filters.Query, ss.Filters.Location, len(ss.SeenKeys), orDash(ss.LastRun))
			}
			return nil
		},
	}
}

func newSavedShowCmd(flags *rootFlags) *cobra.Command {
	return &cobra.Command{
		Use:         "show <name>",
		Short:       "Show a saved search's definition.",
		Example:     "  indeed-pp-cli saved show daily-remote --json",
		Annotations: map[string]string{"mcp:read-only": "true"},
		RunE: func(cmd *cobra.Command, args []string) error {
			if len(args) == 0 {
				return cmd.Help()
			}
			ss, db, err := loadSaved(cmd.Context(), args[0])
			if err != nil {
				return err
			}
			db.Close()
			return printJSONFiltered(cmd.OutOrStdout(), ss, flags)
		},
	}
}

