func newTrackedCmd(flags *rootFlags) *cobra.Command {
	return &cobra.Command{
		Use:         "tracked",
		Short:       "List your shortlisted jobs.",
		Example:     "  indeed-pp-cli tracked --json",
		Annotations: map[string]string{"mcp:read-only": "true"},
		RunE: func(cmd *cobra.Command, args []string) error {
			db, err := openIndeedStore(cmd.Context())
			if err != nil {
				return err
			}
			defer db.Close()
			raws, err := db.List("tracked", 500)
			if err != nil {
				return err
			}
			var list []trackedJob
			for _, r := range raws {
				var tj trackedJob
				if json.Unmarshal(r, &tj) == nil {
					list = append(list, tj)
				}
			}
			if list == nil {
				list = []trackedJob{}
			}
			if flags.asJSON || !isTerminal(cmd.OutOrStdout()) {
				return printJSONFiltered(cmd.OutOrStdout(), list, flags)
			}
			if len(list) == 0 {
				fmt.Fprintln(cmd.OutOrStdout(), "No tracked jobs. Add one with `track <job-key>`.")
				return nil
			}
			for _, tj := range list {
				title := tj.Key
				if tj.Job != nil {
					title = fmt.Sprintf("%s · %s", tj.Job.Title, tj.Job.Company)
				}
				fmt.Fprintf(cmd.OutOrStdout(), "%s\n  %s%s\n", title, viewJobBase+tj.Key, "")
			}
			return nil
		},
	}
}

func newApplyCmd(flags *rootFlags) *cobra.Command {
	var open bool
	cmd := &cobra.Command{
		Use:   "apply <job-key>",
		Short: "Print (or open) a job's application page.",
		Long: "Prints the Indeed listing/apply URL for a job key so you can apply yourself.\n" +
			"This CLI never submits applications. Pass --open to launch it in your browser.",
		Example:     "  indeed-pp-cli apply 3700db3b90d43bc1 --open",
		Annotations: map[string]string{"pp:no-error-path-probe": "true"},
		RunE: func(cmd *cobra.Command, args []string) error {
			if len(args) == 0 {
				return cmd.Help()
			}
			if dryRunOK(flags) {
				return nil
			}
			url := viewJobBase + args[0]
			if !open || cliutil.IsVerifyEnv() {
				fmt.Fprintln(cmd.OutOrStdout(), "would open:", url)
				return nil
			}
			if err := openInBrowser(url); err != nil {
				fmt.Fprintln(cmd.OutOrStdout(), url)
				return fmt.Errorf("could not launch browser (open the URL above manually): %w", err)
			}
			fmt.Fprintln(cmd.OutOrStdout(), "opened:", url)
			return nil
		},
	}
	cmd.Flags().BoolVar(&open, "open", false, "Launch the application page in your browser.")
	return cmd
}

func openInBrowser(url string) error {
	var bin string
	var args []string
	switch runtime.GOOS {
	case "darwin":
		bin = "open"
		args = []string{url}
	case "windows":
		bin = "rundll32"
		args = []string{"url.dll,FileProtocolHandler", url}
	default:
		bin = "xdg-open"
		args = []string{url}
	}
	return exec.Command(bin, args...).Start()
}

func orDash(s string) string {
	if s == "" {
		return "-"
	}
	return s
}
